    simple:
      'Уяви, що твій JS-код — це режисер, а нативна платформа — актори. Режисер не виходить на сцену сам: він каже «покажи текст отут, кнопку отам», а грають справжні нативні елементи. Тому кнопка в React Native — це не div зі стилями, схожими на кнопку, а справжній нативний елемент платформи з рідною анімацією натискання, рідним ефектом ripple на Android і правильною поведінкою при доступності. Твій JavaScript працює в окремому рушії всередині застосунку (зараз це Hermes), а не в браузері: тут немає window, немає document, немає DOM і немає CSS у звичному вигляді. Стилі задаються обʼєктами JS, а верстка рахується движком Yoga за правилами Flexbox. Головний висновок для співбесіди: React Native ділить із React модель компонентів, стан і хуки, але шар відображення в нього повністю інший.',
