    simple:
      'Уяви React як драматурга, що пише пʼєсу з ремарками «персонаж заходить», «персонаж сідає», але саму пʼєсу можна поставити на різних сценах. react-dom ставить цю пʼєсу в браузері: ремарка «заходить» перетворюється на створення елемента div чи span у DOM. react-native ставить ту саму пʼєсу на мобільному пристрої: та сама ремарка перетворюється на створення нативного UIView чи android.view.View. Драматург, тобто пакет react, ніде не змінюється: useState, useEffect, компоненти, узгодження дерева через reconciler — усе це той самий код незалежно від того, де його виконують. Різниця повністю в шарі під назвою host config, який кожен рендерер реалізує по-своєму: він каже React, як створити вузол, як додати дочірній елемент, як застосувати зміну властивості. Саме тому JSX <View> у React Native і <div> у React вебі виглядають схожими синтаксично, але компілюються в геть різні виклики: перший — у створення нативного обʼєкта через міст чи JSI, другий — у виклик document.createElement. Практичний наслідок для розробника: логіку на кшталт кастомних хуків, контексту чи бізнес-правил можна писати один раз і ділити між вебом і мобільним застосунком, а компоненти верстки — ні, бо View і Text не мають прямих еквівалентів у DOM.',
