      'KeyboardAvoidingView — окремий базовий компонент, що автоматично підіймає вміст над клавіатурою, і поведінка behavior відрізняється між iOS (padding) і Android (height чи position) за замовчуванням.',
      'Modal за замовчуванням не має власного фону-затемнення позаду вмісту — його додають вручну стилем, інакше контент під модальним вікном лишається повністю видимим крізь прозорий бекдроп.',
