    simple:
      'Думай про це як про кухню ресторану. JS-потік — це шеф, який вирішує, що готувати: він тримає стан, реагує на натискання, вирішує, що саме показати. Головний потік — це офіціант, який виносить страви до столу: він фізично малює те, що бачить користувач, і приймає його дотики. Потік розкладки — це людина, яка розставляє тарілки на таці, тобто рахує, скільки місця займе кожен елемент. Ці троє працюють паралельно й спілкуються повідомленнями. Проблема виникає, коли шеф зависає над однією стравою: офіціант ще винесе те, що вже готове, тому анімація на нативному боці не зупиниться, але нових страв не буде — застосунок ніби живий, а на натискання не відповідає. Це найчастіша причина скарги «застосунок гальмує», хоча CPU майже вільний: JS-потік просто зайнятий одним довгим синхронним завданням. Саме тому важкі обчислення виносять із JS-потоку, а анімації намагаються виконувати повністю на UI-потоці, щоб вони не залежали від зайнятості JavaScript.',
