        label: 'HostObject: синхронне читання без bridge',
        code: `// C++: HostObject, чиї властивості читає нативний код напряму
class DeviceInfo : public jsi::HostObject {
  jsi::Value get(jsi::Runtime& rt, const jsi::PropNameID& name) override {
    auto propName = name.utf8(rt);
    if (propName == "batteryLevel") {
      return jsi::Value(getCurrentBatteryLevel()); // синхронно, без промісу
    }
    return jsi::Value::undefined();
  }
};

// ❌ через старий bridge — асинхронно і з серіалізацією
const level = await NativeModules.Battery.getLevel();

// ✅ через JSI — синхронний виклик, як звичайна властивість обʼєкта
const level = global.DeviceInfo.batteryLevel;`,
