    simple:
      'Головна зміна проста: замість того щоб передавати одне одному записки, JS і нативний код тепер мають спільний стіл, на який обидва бачать. Технічно це означає, що JavaScript отримує обʼєкт, за яким стоїть справжній нативний обʼєкт у памʼяті, і виклик методу на ньому — це прямий виклик C++, а не повідомлення в черзі. Далі кожна частина вирішує свою стару проблему. Fabric прибирає болі рендеру: дерево елементів тепер живе в C++, а не дублюється окремо на iOS і Android, тому поведінка стала однаковою, а вимірювання й розкладка можуть відбуватись синхронно — саме тому в списках зникло характерне мигтіння порожніми блоками. TurboModules прибирають біль старту: раніше при запуску створювались усі нативні модулі, навіть ті, до яких застосунок ніколи не звернеться, тепер модуль створюється при першому зверненні. Codegen прибирає біль типів: ти описуєш інтерфейс модуля типами TypeScript, а генератор робить із них нативні заголовки, і якщо ти в JS передаси рядок туди, де очікується число, це впаде на збірці, а не в користувача на телефоні. Практичний висновок: усе це відбувається під капотом, і звичайний код застосунку писати інакше не потрібно — зміни відчуваються як менші затримки, швидший старт і менше платформозалежних дивацтв.',
