    why: 'На телефоні критичний ресурс — не пікова швидкість обчислень, а час холодного старту й обсяг памʼяті. Класичні рушії при запуску мають прочитати й розібрати весь JS-бандл, а це на слабкому Android-пристрої могло займати секунди. Hermes переносить цю роботу на етап збірки: на пристрій приїжджає вже готовий байткод.',
    simple:
      'Різниця приблизно як між тим, щоб дати людині книжку іноземною мовою зі словником, і тим, щоб дати їй уже готовий переклад. Звичайний рушій отримує текст програми і мусить кожного запуску його розібрати, перш ніж почати виконувати. Hermes отримує вже перекладену версію — байткод — і починає виконувати майже одразу. Побічний ефект приємний: байткод можна не тримати повністю в памʼяті, а читати з файлу шматками, тому й памʼяті витрачається менше. Другий важливий момент — збирання сміття. Hermes використовує збирач, спроєктований так, щоб не робити довгих пауз, бо пауза в 200 мілісекунд на мобільному — це видимий ривок анімації. Компроміс теж є: у Hermes історично не було повноцінного JIT, тому на довгих важких обчисленнях у чистому JavaScript він може поступатись V8. Але для типового застосунку, де JS переважно керує інтерфейсом і робить мережеві запити, виграш у старті значно важливіший за програш у синтетичних тестах.',
