      'На Android апаратна чи жестова кнопка назад автоматично викликає navigation.goBack для верхнього екрана стека без додаткового коду, якщо не перехоплена вручну через BackHandler.',
      'route.params зберігається в стеку разом з екраном і переживає повернення на попередній екран і назад — це не глобальний стан, а частина конкретного запису історії навігації.',
      'Глибокий стек із десятків екранів утримує змонтованими всі попередні компоненти під капотом, і саме це, а не сам факт навігації, є типовою причиною росту споживання памʼяті в застосунках зі складною ієрархією переходів.',
