      'ArrayBuffer як тип повернення підтримується в TurboModule-специфікаціях нової архітектури через Codegen, тоді як у старому bridge бінарні дані завжди йшли через base64-рядок.',
      'NativeEventEmitter вимагає ручного виклику remove() при розмонтуванні компонента — підписка, що лишилась активною після unmount, продовжує тримати посилання на вже незмонтований компонент.',
