        text: 'Коли react-native встановлений один раз у корені монорепи, а не окремо в кожному застосунку через workspaces, стандартний пошук пакета в локальних node_modules нічого не знаходить. reactNativePath явно вказує CLI справжній шлях до пакета react-native.',
