      'TypeScript-типізація дії через union type з полем type дозволяє switch у reducer звужувати тип payload для кожного case автоматично, без явного приведення типів усередині гілки.',
      'React у деяких випадках може викликати reducer двічі за один dispatch у Strict Mode для виявлення побічних ефектів, тому reducer обовʼязково має лишатись чистою функцією без мутацій і зовнішніх викликів.',
