      'redux-saga під капотом реалізує власний cooperative-scheduler поверх генераторів: кожен yield-ефект типу call чи put обробляється центральним циклом бібліотеки, а не рушієм JS напряму.',
      'У специфікації ECMAScript async-функція десугарується в генератор, обгорнутий вбудованою функцією-драйвером AsyncFunctionStart, яка й підписується на кожен yield-проміс через мікротаск — той самий механізм, що й у бібліотек типу co.',
      'Порівняння швидкості yield і await має сенс лише в однаковому режимі використання: для чистого потоку значень генератор виграє через відсутність черги, а для асинхронного керування обидва підходи зрештою впираються в ту саму мікротаск-чергу специфікації.',
