      'OTA-оновлення через EAS Update чи CodePush не можуть додати новий нативний модуль, дозвіл чи змінити конфігурацію Info.plist — Apple Review Guidelines пункт 3.3.2 прямо забороняє підміну виконуваного коду.',
      'Apple Developer Program коштує 99 доларів на рік і без активної підписки Distribution-сертифікат для випуску в App Store видати неможливо.',
