      'Краш-репортинг і аналітика в React Native — це два окремі шари SDK, підключені нативно: Sentry чи Firebase Crashlytics ловлять і необроблені JS-помилки через глобальний обробник, і нативні краші iOS/Android через код, який стартує ще до ініціалізації JS-рушія. Аналітичні SDK на кшталт Firebase Analytics чи Amplitude окремо збирають події користувача — екрани, тапи, конверсії — і пакетно відправляють їх на бекенд, не блокуючи інтерфейс. Обидва типи інструментів працюють навіть якщо застосунок аварійно завершився: SDK записує звіт локально до перезапуску процесу. Без символізації такий звіт — набір адрес памʼяті, тому CI додатково завантажує source maps для JS і dSYM чи ProGuard mapping для нативного коду.',
