    simple:
      'Уяви, що в застосунку одночасно працюють дві незалежні системи спостереження. Перша встановлюється нативним кодом ще до того, як стартує будь-який JS: вона підписується на сигнали ОС на кшталт SIGSEGV на iOS чи ловить непіймані Java Throwable на Android, тому бачить навіть краш, який стався до того, як JS-рушій узагалі запустився. Друга система живе в JS і підписується через ErrorUtils.setGlobalHandler на непіймані помилки й необроблені відхилення промісів — це той шар, який ловить власні баги в логіці екранів. Коли застосунок падає, SDK не намагається одразу відправити звіт мережею, бо процес уже помирає: натомість він записує деталі краху у файл на диску і відправляє його вже під час наступного запуску застосунку. Кожен звіт супроводжують хлібними крихтами — послідовністю останніх дій користувача чи мережевих запитів перед крахом, які збираються автоматично або вручну через виклик на кшталт addBreadcrumb. Сирий стектрейс із релізної збірки нечитабельний: JS-код мінімізований Metro, Android-код обфускований ProGuard чи R8, а нативний iOS-код узагалі показує лише адреси памʼяті. Тому CI під час збірки завантажує в сервіс краш-репортингу source map для JS, файл dSYM для iOS і mapping.txt для Android — без цього кроку кожен звіт про краш перетворюється на нечитабельний набір символів.',
